import {button,badge,notice} from '../components/ui.js';
import {titleBlock} from './views.js';
export function systemView(tokenSource) {
  const colors = tokenSource ? Object.entries(tokenSource.tokens).filter(([key])=>['color-bg','color-surface','color-text','color-primary','color-muted','color-accent-soft','color-warning','color-danger'].includes(key)) : [];
  return titleBlock('Um sistema, em cada detalhe.','Componentes e estados consumindo a mesma fonte de tokens do protótipo.') +
    `<section class="system-section"><h2>Cores com função</h2><div class="swatch-grid">${colors.map(([key])=>`<div class="swatch"><span style="background:var(--${key})"></span><strong>${key.replace('color-','')}</strong><code>--${key}</code></div>`).join('')}</div></section><section class="system-section"><h2>Tipografia e hierarquia</h2><div class="type-specimen"><p class="display-example">O valor está nos detalhes.</p><p>Manrope para leitura, controles e dados. Bricolage Grotesque para os títulos que orientam a exploração.</p><span class="number-example">R$ 1.850 <span class="muted small">valores alinhados, leitura imediata</span></span></div></section>
    <section class="system-section"><h2>Ações e estados</h2><div class="component-line">${button({label:'Ver detalhes',attributes:'data-action="component-demo"'})}${button({label:'Editar interesses',variant:'secondary',iconName:'sliders',attributes:'data-action="component-demo"'})}${button({label:'Salvar',loading:true})}${button({label:'Indisponível',disabled:true})}</div></section>
    <section class="system-section"><h2>Informação além da cor</h2><div class="component-line">${badge('Funcionamento informado','positive','check')}${badge('Condição não confirmada','warning','info')}${badge('Defeito informado','danger','info')}${badge('Estimativa indisponível','info','info')}</div></section>
    <section class="system-section"><h2>Campos e feedback</h2><div class="two-fields"><div class="field"><label for="example-normal">Nome ou modelo</label><input id="example-normal" placeholder="Ex.: Sony a6000"><small>Rótulo visível e ajuda junto ao campo.</small></div><div class="field"><label for="example-error">Nome ou modelo</label><input id="example-error" aria-invalid="true" aria-describedby="example-error-help"><small id="example-error-help" class="field-error">Informe um nome ou modelo para adicionar o produto.</small></div></div></section>
    <section class="system-section"><h2>Estados de operação</h2><div class="stack">${notice({title:'Configurações salvas',text:'Confirme apenas o que foi gravado com sucesso.',kind:'positive'})}${notice({title:'A coleta não foi atualizada',text:'Mantenha a última informação conhecida e explique como tentar novamente.',kind:'warning'})}${notice({title:'Não foi possível salvar',text:'Preserve os campos preenchidos e indique o que pode ser corrigido.',kind:'danger'})}</div></section>`;
}

